def multiply(self, operand, operand2=None, **kwargs):
    return self._prepare_then_do_arithmetic(
        np.multiply, operand, operand2, **kwargs
    )

def _denormalize_sky(self, sky):
    if self.wcs.lngtyp != 'RA':
        raise ValueError(
            "WCS does not have longitude type of 'RA', therefore " +
            "(ra, dec) data can not be used as input")
    if self.wcs.lattyp != 'DEC':
        raise ValueError(
            "WCS does not have longitude type of 'DEC', therefore " +
            "(ra, dec) data can not be used as input")
    if self.wcs.naxis == 2:
        if self.wcs.lng == 0 and self.wcs.lat == 1:
            return sky
        elif self.wcs.lng == 1 and self.wcs.lat == 0:
            # Reverse the order of the columns
            return sky[:, ::-1]
        else:
            raise ValueError(
                "WCS does not have longitude and latitude celestial " +
                "axes, therefore (ra, dec) data can not be used as input")
    else:
        if self.wcs.lng < 0 or self.wcs.lat < 0:
            raise ValueError(
                "WCS does not have both longitude and latitude "
                "celestial axes, therefore (ra, dec) data can not be " +
                "used as input")
        out = np.zeros((sky.shape[0], self.wcs.naxis))
        out[:, self.wcs.lng] = sky[:, 0]
        out[:, self.wcs.lat] = sky[:, 1]
        return out

def _normalize_sky(self, sky):
    if self.wcs.lngtyp != 'RA':
        raise ValueError(
            "WCS does not have longitude type of 'RA', therefore " +
            "(ra, dec) data can not be returned")
    if self.wcs.lattyp != 'DEC':
        raise ValueError(
            "WCS does not have longitude type of 'DEC', therefore " +
            "(ra, dec) data can not be returned")
    if self.wcs.naxis == 2:
        if self.wcs.lng == 0 and self.wcs.lat == 1:
            return sky
        elif self.wcs.lng == 1 and self.wcs.lat == 0:
            # Reverse the order of the columns
            return sky[:, ::-1]
        else:
            raise ValueError(
                "WCS does not have longitude and latitude celestial "
                "axes, therefore (ra, dec) data can not be returned")
    else:
        if self.wcs.lng < 0 or self.wcs.lat < 0:
            raise ValueError(
                "WCS does not have both longitude and latitude celestial "
                "axes, therefore (ra, dec) data can not be returned")
        out = np.empty((sky.shape[0], 2))
        out[:, 0] = sky[:, self.wcs.lng]
        out[:, 1] = sky[:, self.wcs.lat]
        return out

def _parse_keysel(keysel):
    keysel_flags = 0
    if keysel is not None:
        for element in keysel:
            if element.lower() == 'image':
                keysel_flags |= _wcs.WCSHDR_IMGHEAD
            elif element.lower() == 'binary':
                keysel_flags |= _wcs.WCSHDR_BIMGARR
            elif element.lower() == 'pixel':
                keysel_flags |= _wcs.WCSHDR_PIXLIST
            else:
                raise ValueError(
                    "keysel must be a list of 'image', 'binary' " +
                    "and/or 'pixel'")
    else:
        keysel_flags = -1

    return keysel_flags

def _return_single_array(xy, origin):
    if xy.shape[-1] != self.naxis:
        raise ValueError(
            "When providing two arguments, the array must be "
            "of shape (N, {0})".format(self.naxis))
    if ra_dec_order and sky == 'input':
        xy = self._denormalize_sky(xy)
    result = func(xy, origin)
    if ra_dec_order and sky == 'output':
        result = self._normalize_sky(result)
    return result

def write_array(name, a):
    if a is None:
        return
    size = a.shape[0]
    keywords[str('{0}_ORDER').format(name)] = size - 1
    for i in range(size):
        for j in range(size - i):
            if a[i, j] != 0.0:
                keywords[
                    str('{0}_{1:d}_{2:d}').format(name, i, j)] = a[i, j]

def iter_modules_and_files(modules, extra_files):
    """Iterate through all modules needed to be watched."""
    sys_file_paths = []
    for module in modules:
        # During debugging (with PyDev) the 'typing.io' and 'typing.re' objects
        # are added to sys.modules, however they are types not modules and so
        # cause issues here.
        if not isinstance(module, ModuleType):
            continue
        if module.__name__ == '__main__':
            # __main__ (usually manage.py) doesn't always have a __spec__ set.
            # Handle this by falling back to using __file__, resolved below.
            # See https://docs.python.org/reference/import.html#main-spec
            # __file__ may not exists, e.g. when running ipdb debugger.
            if hasattr(module, '__file__'):
                sys_file_paths.append(module.__file__)
            continue
        if getattr(module, '__spec__', None) is None:
            continue
        spec = module.__spec__
        # Modules could be loaded from places without a concrete location. If
        # this is the case, skip them.
        if spec.has_location:
            origin = spec.loader.archive if isinstance(spec.loader, zipimporter) else spec.origin
            sys_file_paths.append(origin)

    results = set()
    for filename in itertools.chain(sys_file_paths, extra_files):
        if not filename:
            continue
        path = Path(filename)
        try:
            resolved_path = path.resolve(strict=True).absolute()
        except FileNotFoundError:
            # The module could have been removed, don't fail loudly if this
            # is the case.
            continue
        results.add(resolved_path)
    return frozenset(results)

def snapshot_files(self):
    # watched_files may produce duplicate paths if globs overlap.
    seen_files = set()
    for file in self.watched_files():
        if file in seen_files:
            continue
        try:
            mtime = file.stat().st_mtime
        except OSError:
            # This is thrown when the file does not exist.
            continue
        seen_files.add(file)
        yield file, mtime

def watched_files(self, include_globs=True):
    """
    Yield all files that need to be watched, including module files and
    files within globs.
    """
    yield from iter_all_python_module_files()
    yield from self.extra_files
    if include_globs:
        for directory, patterns in self.directory_globs.items():
            for pattern in patterns:
                yield from directory.glob(pattern)

def run(self, **options):
    """Run the server, using the autoreloader if needed."""
    use_reloader = options['use_reloader']

    if use_reloader:
        autoreload.run_with_reloader(self.inner_run, **options)
    else:
        self.inner_run(None, **options)

def run_with_reloader(main_func, *args, **kwargs):
    signal.signal(signal.SIGTERM, lambda *args: sys.exit(0))
    try:
        if os.environ.get(DJANGO_AUTORELOAD_ENV) == 'true':
            reloader = get_reloader()
            logger.info('Watching for file changes with %s', reloader.__class__.__name__)
            start_django(reloader, main_func, *args, **kwargs)
        else:
            exit_code = restart_with_reloader()
            sys.exit(exit_code)
    except KeyboardInterrupt:
        pass

def ensure_echo_on():
    """
    Ensure that echo mode is enabled. Some tools such as PDB disable
    it which causes usability issues after reload.
    """
    if not termios or not sys.stdin.isatty():
        return
    attr_list = termios.tcgetattr(sys.stdin)
    if not attr_list[3] & termios.ECHO:
        attr_list[3] |= termios.ECHO
        if hasattr(signal, 'SIGTTOU'):
            old_handler = signal.signal(signal.SIGTTOU, signal.SIG_IGN)
        else:
            old_handler = None
        termios.tcsetattr(sys.stdin, termios.TCSANOW, attr_list)
        if old_handler is not None:
            signal.signal(signal.SIGTTOU, old_handler)

def check_errors(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        global _exception
        try:
            fn(*args, **kwargs)
        except Exception:
            _exception = sys.exc_info()

            et, ev, tb = _exception

            if getattr(ev, 'filename', None) is None:
                # get the filename from the last item in the stack
                filename = traceback.extract_tb(tb)[-1][0]
            else:
                filename = ev.filename

            if filename not in _error_files:
                _error_files.append(filename)

            raise

    return wrapper

def _get_FIELD_display(self, field):
    value = getattr(self, field.attname)
    # force_str() to coerce lazy strings.
    return force_str(dict(field.flatchoices).get(value, value), strings_only=True)

def __init__(self, *args, **kwargs):
    # Alias some things as locals to avoid repeat global lookups
    cls = self.__class__
    opts = self._meta
    _setattr = setattr
    _DEFERRED = DEFERRED

    pre_init.send(sender=cls, args=args, kwargs=kwargs)

    # Set up the storage for instance state
    self._state = ModelState()

    # There is a rather weird disparity here; if kwargs, it's set, then args
    # overrides it. It should be one or the other; don't duplicate the work
    # The reason for the kwargs check is that standard iterator passes in by
    # args, and instantiation for iteration is 33% faster.
    if len(args) > len(opts.concrete_fields):
        # Daft, but matches old exception sans the err msg.
        raise IndexError("Number of args exceeds number of fields")

    if not kwargs:
        fields_iter = iter(opts.concrete_fields)
        # The ordering of the zip calls matter - zip throws StopIteration
        # when an iter throws it. So if the first iter throws it, the second
        # is *not* consumed. We rely on this, so don't change the order
        # without changing the logic.
        for val, field in zip(args, fields_iter):
            if val is _DEFERRED:
                continue
            _setattr(self, field.attname, val)
    else:
        # Slower, kwargs-ready version.
        fields_iter = iter(opts.fields)
        for val, field in zip(args, fields_iter):
            if val is _DEFERRED:
                continue
            _setattr(self, field.attname, val)
            kwargs.pop(field.name, None)

    # Now we're left with the unprocessed fields that *must* come from
    # keywords, or default.

    for field in fields_iter:
        is_related_object = False
        # Virtual field
        if field.attname not in kwargs and field.column is None:
            continue
        if kwargs:
            if isinstance(field.remote_field, ForeignObjectRel):
                try:
                    # Assume object instance was passed in.
                    rel_obj = kwargs.pop(field.name)
                    is_related_object = True
                except KeyError:
                    try:
                        # Object instance wasn't passed in -- must be an ID.
                        val = kwargs.pop(field.attname)
                    except KeyError:
                        val = field.get_default()
            else:
                try:
                    val = kwargs.pop(field.attname)
                except KeyError:
                    # This is done with an exception rather than the
                    # default argument on pop because we don't want
                    # get_default() to be evaluated, and then not used.
                    # Refs #12057.
                    val = field.get_default()
        else:
            val = field.get_default()

        if is_related_object:
            # If we are passed a related instance, set it using the
            # field.name instead of field.attname (e.g. "user" instead of
            # "user_id") so that the object gets properly cached (and type
            # checked) by the RelatedObjectDescriptor.
            if rel_obj is not _DEFERRED:
                _setattr(self, field.name, rel_obj)
        else:
            if val is not _DEFERRED:
                _setattr(self, field.attname, val)

    if kwargs:
        property_names = opts._property_names
        for prop in tuple(kwargs):
            try:
                # Any remaining kwargs must correspond to properties or
                # virtual fields.
                if prop in property_names or opts.get_field(prop):
                    if kwargs[prop] is not _DEFERRED:
                        _setattr(self, prop, kwargs[prop])
                    del kwargs[prop]
            except (AttributeError, FieldDoesNotExist):
                pass
        for kwarg in kwargs:
            raise TypeError("%s() got an unexpected keyword argument '%s'" % (cls.__name__, kwarg))
    super().__init__()
    post_init.send(sender=cls, instance=self)

def __new__(cls, name, bases, attrs, **kwargs):
    super_new = super().__new__

    # Also ensure initialization is only performed for subclasses of Model
    # (excluding Model class itself).
    parents = [b for b in bases if isinstance(b, ModelBase)]
    if not parents:
        return super_new(cls, name, bases, attrs)

    # Create the class.
    module = attrs.pop('__module__')
    new_attrs = {'__module__': module}
    classcell = attrs.pop('__classcell__', None)
    if classcell is not None:
        new_attrs['__classcell__'] = classcell
    attr_meta = attrs.pop('Meta', None)
    # Pass all attrs without a (Django-specific) contribute_to_class()
    # method to type.__new__() so that they're properly initialized
    # (i.e. __set_name__()).
    contributable_attrs = {}
    for obj_name, obj in list(attrs.items()):
        if _has_contribute_to_class(obj):
            contributable_attrs[obj_name] = obj
        else:
            new_attrs[obj_name] = obj
    new_class = super_new(cls, name, bases, new_attrs, **kwargs)

    abstract = getattr(attr_meta, 'abstract', False)
    meta = attr_meta or getattr(new_class, 'Meta', None)
    base_meta = getattr(new_class, '_meta', None)

    app_label = None

    # Look for an application configuration to attach the model to.
    app_config = apps.get_containing_app_config(module)

    if getattr(meta, 'app_label', None) is None:
        if app_config is None:
            if not abstract:
                raise RuntimeError(
                    "Model class %s.%s doesn't declare an explicit "
                    "app_label and isn't in an application in "
                    "INSTALLED_APPS." % (module, name)
                )

        else:
            app_label = app_config.label

    new_class.add_to_class('_meta', Options(meta, app_label))
    if not abstract:
        new_class.add_to_class(
            'DoesNotExist',
            subclass_exception(
                'DoesNotExist',
                tuple(
                    x.DoesNotExist for x in parents if hasattr(x, '_meta') and not x._meta.abstract
                ) or (ObjectDoesNotExist,),
                module,
                attached_to=new_class))
        new_class.add_to_class(
            'MultipleObjectsReturned',
            subclass_exception(
                'MultipleObjectsReturned',
                tuple(
                    x.MultipleObjectsReturned for x in parents if hasattr(x, '_meta') and not x._meta.abstract
                ) or (MultipleObjectsReturned,),
                module,
                attached_to=new_class))
        if base_meta and not base_meta.abstract:
            # Non-abstract child classes inherit some attributes from their
            # non-abstract parent (unless an ABC comes before it in the
            # method resolution order).
            if not hasattr(meta, 'ordering'):
                new_class._meta.ordering = base_meta.ordering
            if not hasattr(meta, 'get_latest_by'):
                new_class._meta.get_latest_by = base_meta.get_latest_by

    is_proxy = new_class._meta.proxy

    # If the model is a proxy, ensure that the base class
    # hasn't been swapped out.
    if is_proxy and base_meta and base_meta.swapped:
        raise TypeError("%s cannot proxy the swapped model '%s'." % (name, base_meta.swapped))

    # Add remaining attributes (those with a contribute_to_class() method)
    # to the class.
    for obj_name, obj in contributable_attrs.items():
        new_class.add_to_class(obj_name, obj)

    # All the fields of any type declared on this model
    new_fields = chain(
        new_class._meta.local_fields,
        new_class._meta.local_many_to_many,
        new_class._meta.private_fields
    )
    field_names = {f.name for f in new_fields}

    # Basic setup for proxy models.
    if is_proxy:
        base = None
        for parent in [kls for kls in parents if hasattr(kls, '_meta')]:
            if parent._meta.abstract:
                if parent._meta.fields:
                    raise TypeError(
                        "Abstract base class containing model fields not "
                        "permitted for proxy model '%s'." % name
                    )
                else:
                    continue
            if base is None:
                base = parent
            elif parent._meta.concrete_model is not base._meta.concrete_model:
                raise TypeError("Proxy model '%s' has more than one non-abstract model base class." % name)
        if base is None:
            raise TypeError("Proxy model '%s' has no non-abstract model base class." % name)
        new_class._meta.setup_proxy(base)
        new_class._meta.concrete_model = base._meta.concrete_model
    else:
        new_class._meta.concrete_model = new_class

    # Collect the parent links for multi-table inheritance.
    parent_links = {}
    for base in reversed([new_class] + parents):
        # Conceptually equivalent to `if base is Model`.
        if not hasattr(base, '_meta'):
            continue
        # Skip concrete parent classes.
        if base != new_class and not base._meta.abstract:
            continue
        # Locate OneToOneField instances.
        for field in base._meta.local_fields:
            if isinstance(field, OneToOneField):
                related = resolve_relation(new_class, field.remote_field.model)
                parent_links[make_model_tuple(related)] = field

    # Track fields inherited from base models.
    inherited_attributes = set()
    # Do the appropriate setup for any model parents.
    for base in new_class.mro():
        if base not in parents or not hasattr(base, '_meta'):
            # Things without _meta aren't functional models, so they're
            # uninteresting parents.
            inherited_attributes.update(base.__dict__)
            continue

        parent_fields = base._meta.local_fields + base._meta.local_many_to_many
        if not base._meta.abstract:
            # Check for clashes between locally declared fields and those
            # on the base classes.
            for field in parent_fields:
                if field.name in field_names:
                    raise FieldError(
                        'Local field %r in class %r clashes with field of '
                        'the same name from base class %r.' % (
                            field.name,
                            name,
                            base.__name__,
                        )
                    )
                else:
                    inherited_attributes.add(field.name)

            # Concrete classes...
            base = base._meta.concrete_model
            base_key = make_model_tuple(base)
            if base_key in parent_links:
                field = parent_links[base_key]
            elif not is_proxy:
                attr_name = '%s_ptr' % base._meta.model_name
                field = OneToOneField(
                    base,
                    on_delete=CASCADE,
                    name=attr_name,
                    auto_created=True,
                    parent_link=True,
                )

                if attr_name in field_names:
                    raise FieldError(
                        "Auto-generated field '%s' in class %r for "
                        "parent_link to base class %r clashes with "
                        "declared field of the same name." % (
                            attr_name,
                            name,
                            base.__name__,
                        )
                    )

                # Only add the ptr field if it's not already present;
                # e.g. migrations will already have it specified
                if not hasattr(new_class, attr_name):
                    new_class.add_to_class(attr_name, field)
            else:
                field = None
            new_class._meta.parents[base] = field
        else:
            base_parents = base._meta.parents.copy()

            # Add fields from abstract base class if it wasn't overridden.
            for field in parent_fields:
                if (field.name not in field_names and
                        field.name not in new_class.__dict__ and
                        field.name not in inherited_attributes):
                    new_field = copy.deepcopy(field)
                    new_class.add_to_class(field.name, new_field)
                    # Replace parent links defined on this base by the new
                    # field. It will be appropriately resolved if required.
                    if field.one_to_one:
                        for parent, parent_link in base_parents.items():
                            if field == parent_link:
                                base_parents[parent] = new_field

            # Pass any non-abstract parent classes onto child.
            new_class._meta.parents.update(base_parents)

        # Inherit private fields (like GenericForeignKey) from the parent
        # class
        for field in base._meta.private_fields:
            if field.name in field_names:
                if not base._meta.abstract:
                    raise FieldError(
                        'Local field %r in class %r clashes with field of '
                        'the same name from base class %r.' % (
                            field.name,
                            name,
                            base.__name__,
                        )
                    )
            else:
                field = copy.deepcopy(field)
                if not base._meta.abstract:
                    field.mti_inherited = True
                new_class.add_to_class(field.name, field)

    # Copy indexes so that index names are unique when models extend an
    # abstract model.
    new_class._meta.indexes = [copy.deepcopy(idx) for idx in new_class._meta.indexes]

    if abstract:
        # Abstract base models can't be instantiated and don't appear in
        # the list of models for an app. We do the final setup for them a
        # little differently from normal models.
        attr_meta.abstract = False
        new_class.Meta = attr_meta
        return new_class

    new_class._prepare()
    new_class._meta.apps.register_model(new_class._meta.app_label, new_class)
    return new_class

def get_cleansed_multivaluedict(self, request, multivaluedict):
    """
    Replace the keys in a MultiValueDict marked as sensitive with stars.
    This mitigates leaking sensitive POST parameters if something like
    request.POST['nonexistent_key'] throws an exception (#21098).
    """
    sensitive_post_parameters = getattr(request, 'sensitive_post_parameters', [])
    if self.is_active(request) and sensitive_post_parameters:
        multivaluedict = multivaluedict.copy()
        for param in sensitive_post_parameters:
            if param in multivaluedict:
                multivaluedict[param] = self.cleansed_substitute
    return multivaluedict

def get_post_parameters(self, request):
    """
    Replace the values of POST parameters marked as sensitive with
    stars (*********).
    """
    if request is None:
        return {}
    else:
        sensitive_post_parameters = getattr(request, 'sensitive_post_parameters', [])
        if self.is_active(request) and sensitive_post_parameters:
            cleansed = request.POST.copy()
            if sensitive_post_parameters == '__ALL__':
                # Cleanse all parameters.
                for k in cleansed:
                    cleansed[k] = self.cleansed_substitute
                return cleansed
            else:
                # Cleanse only the specified parameters.
                for param in sensitive_post_parameters:
                    if param in cleansed:
                        cleansed[param] = self.cleansed_substitute
                return cleansed
        else:
            return request.POST

def cleanse_special_types(self, request, value):
    try:
        # If value is lazy or a complex object of another kind, this check
        # might raise an exception. isinstance checks that lazy
        # MultiValueDicts will have a return value.
        is_multivalue_dict = isinstance(value, MultiValueDict)
    except Exception as e:
        return '{!r} while evaluating {!r}'.format(e, value)

    if is_multivalue_dict:
        # Cleanse MultiValueDicts (request.POST is the one we usually care about)
        value = self.get_cleansed_multivaluedict(request, value)
    return value

def getlist(self, key, default=None):
    """
    Return the list of values for the key. If key doesn't exist, return a
    default value.
    """
    return self._getlist(key, default, force_list=True)

def __setattr__(self, name, value):
    """
    Set the value of setting. Clear all cached values if _wrapped changes
    (@override_settings does this) or clear single values when set.
    """
    if name == '_wrapped':
        self.__dict__.clear()
    else:
        self.__dict__.pop(name, None)
    super().__setattr__(name, value)

def get_safe_request_meta(self, request):
    """
    Return a dictionary of request.META with sensitive values redacted.
    """
    if not hasattr(request, 'META'):
        return {}
    return {k: self.cleanse_setting(k, v) for k, v in request.META.items()}

def add_domain(domain, url, secure=False):
    protocol = 'https' if secure else 'http'
    if url.startswith('//'):
        # Support network-path reference (see #16753) - RSS requires a protocol
        url = '%s:%s' % (protocol, url)
    elif not url.startswith(('http://', 'https://', 'mailto:')):
        url = iri_to_uri('%s://%s%s' % (protocol, domain, url))
    return url

def item_extra_kwargs(self, item):
    """
    Return an extra keyword arguments dictionary that is used with
    the `add_item` call of the feed generator.
    """
    return {}

def item_title(self, item):
    # Titles should be double escaped by default (see #6533)
    return escape(str(item))

def item_link(self, item):
    try:
        return item.get_absolute_url()
    except AttributeError:
        raise ImproperlyConfigured(
            'Give your %s class a get_absolute_url() method, or define an '
            'item_link() method in your Feed class.' % item.__class__.__name__
        )

def item_enclosures(self, item):
    enc_url = self._get_dynamic_attr('item_enclosure_url', item)
    if enc_url:
        enc = feedgenerator.Enclosure(
            url=str(enc_url),
            length=str(self._get_dynamic_attr('item_enclosure_length', item)),
            mime_type=str(self._get_dynamic_attr('item_enclosure_mime_type', item)),
        )
        return [enc]
    return []

def _get_session(self, no_load=False):
    """
    Lazily load session from storage (unless "no_load" is True, when only
    an empty dict is stored) and store it in the current instance.
    """
    self.accessed = True
    try:
        return self._session_cache
    except AttributeError:
        if self.session_key is None or no_load:
            self._session_cache = {}
        else:
            self._session_cache = self.load()
    return self._session_cache

def _get_new_session_key(self):
    "Return session key that isn't being used."
    while True:
        session_key = get_random_string(32, VALID_KEY_CHARS)
        if not self.exists(session_key):
            return session_key

def _get_or_create_session_key(self):
    if self._session_key is None:
        self._session_key = self._get_new_session_key()
    return self._session_key

def _set_session_key(self, value):
    """
    Validate session key on assignment. Invalid values will set to None.
    """
    if self._validate_session_key(value):
        self.__session_key = value
    else:
        self.__session_key = None

def get_expiry_age(self, **kwargs):
    """Get the number of seconds until the session expires.

    Optionally, this function accepts `modification` and `expiry` keyword
    arguments specifying the modification and expiry of the session.
    """
    try:
        modification = kwargs['modification']
    except KeyError:
        modification = timezone.now()
    # Make the difference between "expiry=None passed in kwargs" and
    # "expiry not passed in kwargs", in order to guarantee not to trigger
    # self.load() when expiry is provided.
    try:
        expiry = kwargs['expiry']
    except KeyError:
        expiry = self.get('_session_expiry')

    if not expiry:   # Checks both None and 0 cases
        return self.get_session_cookie_age()
    if not isinstance(expiry, datetime):
        return expiry
    delta = expiry - modification
    return delta.days * 86400 + delta.seconds

def get_expiry_date(self, **kwargs):
    """Get session the expiry date (as a datetime object).

    Optionally, this function accepts `modification` and `expiry` keyword
    arguments specifying the modification and expiry of the session.
    """
    try:
        modification = kwargs['modification']
    except KeyError:
        modification = timezone.now()
    # Same comment as in get_expiry_age
    try:
        expiry = kwargs['expiry']
    except KeyError:
        expiry = self.get('_session_expiry')

    if isinstance(expiry, datetime):
        return expiry
    expiry = expiry or self.get_session_cookie_age()
    return modification + timedelta(seconds=expiry)

def get_queryset(self, request):
    queryset = super().get_queryset(request)
    if not self.has_view_or_change_permission(request):
        queryset = queryset.none()
    return queryset

def has_add_permission(self, request, obj):
    if self.opts.auto_created:
        # Auto-created intermediate models don't have their own
        # permissions. The user needs to have the change permission for the
        # related model in order to be able to do anything with the
        # intermediate model.
        return self._has_any_perms_for_target_model(request, ['change'])
    return super().has_add_permission(request)

def has_change_permission(self, request, obj=None):
    if self.opts.auto_created:
        # Same comment as has_add_permission().
        return self._has_any_perms_for_target_model(request, ['change'])
    return super().has_change_permission(request)

def has_delete_permission(self, request, obj=None):
    if self.opts.auto_created:
        # Same comment as has_add_permission().
        return self._has_any_perms_for_target_model(request, ['change'])
    return super().has_delete_permission(request, obj)

def has_view_permission(self, request, obj=None):
    if self.opts.auto_created:
        # Same comment as has_add_permission(). The 'change' permission
        # also implies the 'view' permission.
        return self._has_any_perms_for_target_model(request, ['view', 'change'])
    return super().has_view_permission(request)

