def _map_diag_iter_hue(self, func, **kwargs):
    """Put marginal plot on each diagonal axes, iterating over hue."""
    # Plot on each of the diagonal axes
    fixed_color = kwargs.pop("color", None)

    for var, ax in zip(self.diag_vars, self.diag_axes):
        hue_grouped = self.data[var].groupby(self.hue_vals)

        plot_kwargs = kwargs.copy()
        if str(func.__module__).startswith("seaborn"):
            plot_kwargs["ax"] = ax
        else:
            plt.sca(ax)

        for k, label_k in enumerate(self._hue_order):

            # Attempt to get data for this level, allowing for empty
            try:
                data_k = hue_grouped.get_group(label_k)
            except KeyError:
                data_k = pd.Series([], dtype=float)

            if fixed_color is None:
                color = self.palette[k]
            else:
                color = fixed_color

            if self._dropna:
                data_k = utils.remove_na(data_k)

            if str(func.__module__).startswith("seaborn"):
                func(x=data_k, label=label_k, color=color, **plot_kwargs)
            else:
                func(data_k, label=label_k, color=color, **plot_kwargs)

    self._add_axis_labels()

    return self

def _plot_bivariate(self, x_var, y_var, ax, func, **kwargs):
    """Draw a bivariate plot on the specified axes."""
    if "hue" not in signature(func).parameters:
        self._plot_bivariate_iter_hue(x_var, y_var, ax, func, **kwargs)
        return

    kwargs = kwargs.copy()
    if str(func.__module__).startswith("seaborn"):
        kwargs["ax"] = ax
    else:
        plt.sca(ax)

    if x_var == y_var:
        axes_vars = [x_var]
    else:
        axes_vars = [x_var, y_var]

    if self._hue_var is not None and self._hue_var not in axes_vars:
        axes_vars.append(self._hue_var)

    data = self.data[axes_vars]
    if self._dropna:
        data = data.dropna()

    x = data[x_var]
    y = data[y_var]
    if self._hue_var is None:
        hue = None
    else:
        hue = data.get(self._hue_var)

    if "hue" not in kwargs:
        kwargs.update({
            "hue": hue, "hue_order": self._hue_order, "palette": self._orig_palette,
        })
    func(x=x, y=y, **kwargs)

    self._update_legend_data(ax)

def _plot_bivariate_iter_hue(self, x_var, y_var, ax, func, **kwargs):
    """Draw a bivariate plot while iterating over hue subsets."""
    kwargs = kwargs.copy()
    if str(func.__module__).startswith("seaborn"):
        kwargs["ax"] = ax
    else:
        plt.sca(ax)

    if x_var == y_var:
        axes_vars = [x_var]
    else:
        axes_vars = [x_var, y_var]

    hue_grouped = self.data.groupby(self.hue_vals)
    for k, label_k in enumerate(self._hue_order):

        kws = kwargs.copy()

        # Attempt to get data for this level, allowing for empty
        try:
            data_k = hue_grouped.get_group(label_k)
        except KeyError:
            data_k = pd.DataFrame(columns=axes_vars,
                                  dtype=float)

        if self._dropna:
            data_k = data_k[axes_vars].dropna()

        x = data_k[x_var]
        y = data_k[y_var]

        for kw, val_list in self.hue_kws.items():
            kws[kw] = val_list[k]
        kws.setdefault("color", self.palette[k])
        if self._hue_var is not None:
            kws["label"] = label_k

        if str(func.__module__).startswith("seaborn"):
            func(x=x, y=y, **kws)
        else:
            func(x, y, **kws)

    self._update_legend_data(ax)

def _add_axis_labels(self):
    """Add labels to the left and bottom Axes."""
    for ax, label in zip(self.axes[-1, :], self.x_vars):
        ax.set_xlabel(label)
    for ax, label in zip(self.axes[:, 0], self.y_vars):
        ax.set_ylabel(label)

def get_var(var):
    vector = plot_data.get(var, None)
    if vector is not None:
        vector = vector.rename(p.variables.get(var, None))
    return vector

def _find_numeric_cols(self, data):
    """Find which variables in a DataFrame are numeric."""
    numeric_cols = []
    for col in data:
        if variable_type(data[col]) == "numeric":
            numeric_cols.append(col)
    return numeric_cols

def variable_type(vector, boolean_type="numeric"):
    """
    Determine whether a vector contains numeric, categorical, or datetime data.

    This function differs from the pandas typing API in two ways:

    - Python sequences or object-typed PyData objects are considered numeric if
      all of their entries are numeric.
    - String or mixed-type data are considered categorical even if not
      explicitly represented as a :class:`pandas.api.types.CategoricalDtype`.

    Parameters
    ----------
    vector : :func:`pandas.Series`, :func:`numpy.ndarray`, or Python sequence
        Input data to test.
    boolean_type : 'numeric' or 'categorical'
        Type to use for vectors containing only 0s and 1s (and NAs).

    Returns
    -------
    var_type : 'numeric', 'categorical', or 'datetime'
        Name identifying the type of data in the vector.
    """
    vector = pd.Series(vector)

    # If a categorical dtype is set, infer categorical
    if isinstance(vector.dtype, pd.CategoricalDtype):
        return VariableType("categorical")

    # Special-case all-na data, which is always "numeric"
    if pd.isna(vector).all():
        return VariableType("numeric")

    # At this point, drop nans to simplify further type inference
    vector = vector.dropna()

    # Special-case binary/boolean data, allow caller to determine
    # This triggers a numpy warning when vector has strings/objects
    # https://github.com/numpy/numpy/issues/6784
    # Because we reduce with .all(), we are agnostic about whether the
    # comparison returns a scalar or vector, so we will ignore the warning.
    # It triggers a separate DeprecationWarning when the vector has datetimes:
    # https://github.com/numpy/numpy/issues/13548
    # This is considered a bug by numpy and will likely go away.
    with warnings.catch_warnings():
        warnings.simplefilter(
            action='ignore', category=(FutureWarning, DeprecationWarning)
        )
        if np.isin(vector, [0, 1]).all():
            return VariableType(boolean_type)

    # Defer to positive pandas tests
    if pd.api.types.is_numeric_dtype(vector):
        return VariableType("numeric")

    if pd.api.types.is_datetime64_dtype(vector):
        return VariableType("datetime")

    # --- If we get to here, we need to check the entries

    # Check for a collection where everything is a number

    def all_numeric(x):
        for x_i in x:
            if not isinstance(x_i, Number):
                return False
        return True

    if all_numeric(vector):
        return VariableType("numeric")

    # Check for a collection where everything is a datetime

    def all_datetime(x):
        for x_i in x:
            if not isinstance(x_i, (datetime, np.datetime64)):
                return False
        return True

    if all_datetime(vector):
        return VariableType("datetime")

    # Otherwise, our final fallback is to consider things categorical

    return VariableType("categorical")

def prepare_method(self, method):
    """Prepares the given HTTP method."""
    self.method = method
    if self.method is not None:
        self.method = self.method.upper()

def to_native_string(string, encoding='ascii'):
    """
    Given a string object, regardless of type, returns a representation of that
    string in the native string type, encoding and decoding where necessary.
    This assumes ASCII unless told otherwise.
    """
    out = None

    if isinstance(string, builtin_str):
        out = string
    else:
        if is_py2:
            out = string.encode(encoding)
        else:
            out = string.decode(encoding)

    return out

def merge_environment_settings(self, url, proxies, stream, verify, cert):
    """Check the environment and merge it with some settings."""
    # Gather clues from the surrounding environment.
    if self.trust_env:
        # Set environment's proxies.
        env_proxies = get_environ_proxies(url) or {}
        for (k, v) in env_proxies.items():
            proxies.setdefault(k, v)

        # Look for requests environment configuration and be compatible
        # with cURL.
        if verify is True or verify is None:
            verify = (os.environ.get('REQUESTS_CA_BUNDLE') or
                      os.environ.get('CURL_CA_BUNDLE'))

    # Merge all the kwargs.
    proxies = merge_setting(proxies, self.proxies)
    stream = merge_setting(stream, self.stream)
    verify = merge_setting(verify, self.verify)
    cert = merge_setting(cert, self.cert)

    return {'verify': verify, 'proxies': proxies, 'stream': stream,
            'cert': cert}

def get_adapter(self, url):
    """Returns the appropriate connnection adapter for the given URL."""
    for (prefix, adapter) in self.adapters.items():

        if url.lower().startswith(prefix):
            return adapter

    # Nothing matches :-/
    raise InvalidSchema("No connection adapters were found for '%s'" % url)

def dataset_repr(ds):
    summary = ["<xarray.{}>".format(type(ds).__name__)]

    col_width = _calculate_col_width(_get_col_items(ds.variables))

    dims_start = pretty_print("Dimensions:", col_width)
    summary.append("{}({})".format(dims_start, dim_summary(ds)))

    if ds.coords:
        summary.append(coords_repr(ds.coords, col_width=col_width))

    unindexed_dims_str = unindexed_dims_repr(ds.dims, ds.coords)
    if unindexed_dims_str:
        summary.append(unindexed_dims_str)

    summary.append(data_vars_repr(ds.data_vars, col_width=col_width))

    if ds.attrs:
        summary.append(attrs_repr(ds.attrs))

    return "\n".join(summary)

def __repr__(self):
    return "{}, grouped over {!r} \n{!r} groups with labels {}.".format(
        self.__class__.__name__,
        self._unique_coord.name,
        self._unique_coord.size,
        ", ".join(format_array_flat(self._unique_coord, 30).split()),
    )

def _get_index_and_items(self, index, grouper):
    from .resample_cftime import CFTimeGrouper

    s = pd.Series(np.arange(index.size), index)
    if isinstance(grouper, CFTimeGrouper):
        first_items = grouper.first_items(index)
    else:
        first_items = s.groupby(grouper).first()
        _apply_loffset(grouper, first_items)
    full_index = first_items.index
    if first_items.isnull().any():
        first_items = first_items.dropna()
    return full_index, first_items

def _iter_grouped(self):
    """Iterate over each element in this group"""
    for indices in self._group_indices:
        yield self._obj.isel(**{self._group_dim: indices})

def assertrepr_compare(config, op, left, right):
    """Return specialised explanations for some operators/operands"""
    width = 80 - 15 - len(op) - 2  # 15 chars indentation, 1 space around op
    left_repr = saferepr(left, maxsize=int(width // 2))
    right_repr = saferepr(right, maxsize=width - len(left_repr))

    summary = u"%s %s %s" % (ecu(left_repr), op, ecu(right_repr))

    verbose = config.getoption("verbose")
    explanation = None
    try:
        if op == "==":
            if istext(left) and istext(right):
                explanation = _diff_text(left, right, verbose)
            else:
                if issequence(left) and issequence(right):
                    explanation = _compare_eq_sequence(left, right, verbose)
                elif isset(left) and isset(right):
                    explanation = _compare_eq_set(left, right, verbose)
                elif isdict(left) and isdict(right):
                    explanation = _compare_eq_dict(left, right, verbose)
                elif type(left) == type(right) and (isdatacls(left) or isattrs(left)):
                    type_fn = (isdatacls, isattrs)
                    explanation = _compare_eq_cls(left, right, verbose, type_fn)
                elif verbose > 0:
                    explanation = _compare_eq_verbose(left, right)
                if isiterable(left) and isiterable(right):
                    expl = _compare_eq_iterable(left, right, verbose)
                    if explanation is not None:
                        explanation.extend(expl)
                    else:
                        explanation = expl
        elif op == "not in":
            if istext(left) and istext(right):
                explanation = _notin_text(left, right, verbose)
    except outcomes.Exit:
        raise
    except Exception:
        explanation = [
            u"(pytest_assertion plugin: representation of details failed.  "
            u"Probably an object has a faulty __repr__.)",
            six.text_type(_pytest._code.ExceptionInfo.from_current()),
        ]

    if not explanation:
        return None

    return [summary] + explanation

def builtin(self, name):
    """Return the builtin called *name*."""
    builtin_name = ast.Name("@py_builtins", ast.Load())
    return ast.Attribute(builtin_name, name, ast.Load())

def helper(self, name, *args):
    """Call a helper in this module."""
    py_name = ast.Name("@pytest_ar", ast.Load())
    attr = ast.Attribute(py_name, name, ast.Load())
    return ast_Call(attr, list(args), [])

def _getglobals(self) -> Dict[str, object]:
    d = {"os": os, "sys": sys, "platform": platform, "config": self.item.config}
    if hasattr(self.item, "obj"):
        d.update(self.item.obj.__globals__)  # type: ignore[attr-defined] # noqa: F821
    return d

def cached_eval(config: Config, expr: str, d: Dict[str, object]) -> Any:
    default = {}  # type: Dict[str, object]
    evalcache = config._store.setdefault(evalcache_key, default)
    try:
        return evalcache[expr]
    except KeyError:
        import _pytest._code

        exprcode = _pytest._code.compile(expr, mode="eval")
        evalcache[expr] = x = eval(exprcode, d)
        return x

def _istrue(self) -> bool:
    if hasattr(self, "result"):
        result = getattr(self, "result")  # type: bool
        return result
    self._marks = self._get_marks()

    if self._marks:
        self.result = False
        for mark in self._marks:
            self._mark = mark
            if "condition" not in mark.kwargs:
                args = mark.args
            else:
                args = (mark.kwargs["condition"],)

            for expr in args:
                self.expr = expr
                if isinstance(expr, str):
                    d = self._getglobals()
                    result = cached_eval(self.item.config, expr, d)
                else:
                    if "reason" not in mark.kwargs:
                        # XXX better be checked at collection time
                        msg = (
                            "you need to specify reason=STRING "
                            "when using booleans as conditions."
                        )
                        fail(msg)
                    result = bool(expr)
                if result:
                    self.result = True
                    self.reason = mark.kwargs.get("reason", None)
                    self.expr = expr
                    return self.result

            if not args:
                self.result = True
                self.reason = mark.kwargs.get("reason", None)
                return self.result
    return False

def pytest_runtest_setup(item: Item) -> None:
    # Check if skip or skipif are specified as pytest marks
    item._store[skipped_by_mark_key] = False
    eval_skipif = MarkEvaluator(item, "skipif")
    if eval_skipif.istrue():
        item._store[skipped_by_mark_key] = True
        skip(eval_skipif.getexplanation())

    for skip_info in item.iter_markers(name="skip"):
        item._store[skipped_by_mark_key] = True
        if "reason" in skip_info.kwargs:
            skip(skip_info.kwargs["reason"])
        elif skip_info.args:
            skip(skip_info.args[0])
        else:
            skip("unconditional skip")

    item._store[evalxfail_key] = MarkEvaluator(item, "xfail")
    check_xfail_no_run(item)

def getexplanation(self):
    expl = getattr(self, "reason", None) or self.get("reason", None)
    if not expl:
        if not hasattr(self, "expr"):
            return ""
        else:
            return "condition: " + str(self.expr)
    return expl

def check_xfail_no_run(item: Item) -> None:
    """check xfail(run=False)"""
    if not item.config.option.runxfail:
        evalxfail = item._store[evalxfail_key]
        if evalxfail.istrue():
            if not evalxfail.get("run", True):
                xfail("[NOTRUN] " + evalxfail.getexplanation())

def invalidraise(self, exc) -> Optional[bool]:
    raises = self.get("raises")
    if not raises:
        return None
    return not isinstance(exc, raises)

def __bool__(self) -> bool:
    # don't cache here to prevent staleness
    return bool(self._get_marks())

def _num_samples(x):
    """Return number of samples in array-like x."""
    if hasattr(x, 'fit') and callable(x.fit):
        # Don't get num_samples from an ensembles length!
        raise TypeError('Expected sequence or array-like, got '
                        'estimator %s' % x)
    if not hasattr(x, '__len__') and not hasattr(x, 'shape'):
        if hasattr(x, '__array__'):
            x = np.asarray(x)
        else:
            raise TypeError("Expected sequence or array-like, got %s" %
                            type(x))
    if hasattr(x, 'shape'):
        if len(x.shape) == 0:
            raise TypeError("Singleton array %r cannot be considered"
                            " a valid collection." % x)
        return x.shape[0]
    else:
        return len(x)

def _initialize(self, X, y, init):
    """Initialize the transformation.

    Parameters
    ----------
    X : array-like, shape (n_samples, n_features)
        The training samples.

    y : array-like, shape (n_samples,)
        The training labels.

    init : string or numpy array of shape (n_features_a, n_features_b)
        The validated initialization of the linear transformation.

    Returns
    -------
    transformation : array, shape (n_components, n_features)
        The initialized linear transformation.

    """

    transformation = init
    if self.warm_start and hasattr(self, 'components_'):
        transformation = self.components_
    elif isinstance(init, np.ndarray):
        pass
    else:
        n_samples, n_features = X.shape
        n_components = self.n_components or n_features
        if init == 'auto':
            n_classes = len(np.unique(y))
            if n_components <= min(n_features, n_classes - 1):
                init = 'lda'
            elif n_components < min(n_features, n_samples):
                init = 'pca'
            else:
                init = 'identity'
        if init == 'identity':
            transformation = np.eye(n_components, X.shape[1])
        elif init == 'random':
            transformation = self.random_state_.randn(n_components,
                                                      X.shape[1])
        elif init in {'pca', 'lda'}:
            init_time = time.time()
            if init == 'pca':
                pca = PCA(n_components=n_components,
                          random_state=self.random_state_)
                if self.verbose:
                    print('Finding principal components... ', end='')
                    sys.stdout.flush()
                pca.fit(X)
                transformation = pca.components_
            elif init == 'lda':
                from ..discriminant_analysis import (
                    LinearDiscriminantAnalysis)
                lda = LinearDiscriminantAnalysis(n_components=n_components)
                if self.verbose:
                    print('Finding most discriminative components... ',
                          end='')
                    sys.stdout.flush()
                lda.fit(X, y)
                transformation = lda.scalings_.T[:n_components]
            if self.verbose:
                print('done in {:5.2f}s'.format(time.time() - init_time))
    return transformation

def _check_param_grid(param_grid):
    if hasattr(param_grid, 'items'):
        param_grid = [param_grid]

    for p in param_grid:
        for name, v in p.items():
            if isinstance(v, np.ndarray) and v.ndim > 1:
                raise ValueError("Parameter array should be one-dimensional.")

            if (isinstance(v, str) or
                    not isinstance(v, (np.ndarray, Sequence))):
                raise ValueError("Parameter values for parameter ({0}) need "
                                 "to be a sequence(but not a string) or"
                                 " np.ndarray.".format(name))

            if len(v) == 0:
                raise ValueError("Parameter values for parameter ({0}) need "
                                 "to be a non-empty sequence.".format(name))

def _hstack(self, Xs):
    """Stacks Xs horizontally.

    This allows subclasses to control the stacking behavior, while reusing
    everything else from ColumnTransformer.

    Parameters
    ----------
    Xs : list of {array-like, sparse matrix, dataframe}
    """
    if self.sparse_output_:
        try:
            # since all columns should be numeric before stacking them
            # in a sparse matrix, `check_array` is used for the
            # dtype conversion if necessary.
            converted_Xs = [
                check_array(X, accept_sparse=True, force_all_finite=False)
                for X in Xs
            ]
        except ValueError as e:
            raise ValueError(
                "For a sparse output, all columns should "
                "be a numeric or convertible to a numeric."
            ) from e

        return sparse.hstack(converted_Xs).tocsr()
    else:
        Xs = [f.toarray() if sparse.issparse(f) else f for f in Xs]
        config = _get_output_config("transform", self)
        if config["dense"] == "pandas" and all(hasattr(X, "iloc") for X in Xs):
            pd = check_pandas_support("transform")
            output = pd.concat(Xs, axis=1)

            # If all transformers define `get_feature_names_out`, then transform
            # will adjust the column names to be consistent with
            # verbose_feature_names_out. Here we prefix the feature names if
            # verbose_feature_names_out=True.

            if not self.verbose_feature_names_out:
                return output

            transformer_names = [
                t[0] for t in self._iter(fitted=True, replace_strings=True)
            ]
            feature_names_outs = [X.columns for X in Xs]
            names_out = self._add_prefix_for_feature_names_out(
                list(zip(transformer_names, feature_names_outs))
            )
            output.columns = names_out
            return output

        return np.hstack(Xs)

def _add_prefix_for_feature_names_out(self, transformer_with_feature_names_out):
    """Add prefix for feature names out that includes the transformer names.

    Parameters
    ----------
    transformer_with_feature_names_out : list of tuples of (str, array-like of str)
        The tuple consistent of the transformer's name and its feature names out.

    Returns
    -------
    feature_names_out : ndarray of shape (n_features,), dtype=str
        Transformed feature names.
    """
    if self.verbose_feature_names_out:
        # Prefix the feature names out with the transformers name
        names = list(
            chain.from_iterable(
                (f"{name}__{i}" for i in feature_names_out)
                for name, feature_names_out in transformer_with_feature_names_out
            )
        )
        return np.asarray(names, dtype=object)

    # verbose_feature_names_out is False
    # Check that names are all unique without a prefix
    feature_names_count = Counter(
        chain.from_iterable(s for _, s in transformer_with_feature_names_out)
    )
    top_6_overlap = [
        name for name, count in feature_names_count.most_common(6) if count > 1
    ]
    top_6_overlap.sort()
    if top_6_overlap:
        if len(top_6_overlap) == 6:
            # There are more than 5 overlapping names, we only show the 5
            # of the feature names
            names_repr = str(top_6_overlap[:5])[:-1] + ", ...]"
        else:
            names_repr = str(top_6_overlap)
        raise ValueError(
            f"Output feature names: {names_repr} are not unique. Please set "
            "verbose_feature_names_out=True to add prefixes to feature names"
        )

    return np.concatenate(
        [name for _, name in transformer_with_feature_names_out],
    )

def _iter(self, fitted=False, replace_strings=False, column_as_strings=False):
    """
    Generate (name, trans, column, weight) tuples.

    If fitted=True, use the fitted transformers, else use the
    user specified transformers updated with converted column names
    and potentially appended with transformer for remainder.

    """
    if fitted:
        if replace_strings:
            # Replace "passthrough" with the fitted version in
            # _name_to_fitted_passthrough
            def replace_passthrough(name, trans, columns):
                if name not in self._name_to_fitted_passthrough:
                    return name, trans, columns
                return name, self._name_to_fitted_passthrough[name], columns

            transformers = [
                replace_passthrough(*trans) for trans in self.transformers_
            ]
        else:
            transformers = self.transformers_
    else:
        # interleave the validated column specifiers
        transformers = [
            (name, trans, column)
            for (name, trans, _), column in zip(self.transformers, self._columns)
        ]
        # add transformer tuple for remainder
        if self._remainder[2]:
            transformers = chain(transformers, [self._remainder])
    get_weight = (self.transformer_weights or {}).get

    output_config = _get_output_config("transform", self)
    for name, trans, columns in transformers:
        if replace_strings:
            # replace 'passthrough' with identity transformer and
            # skip in case of 'drop'
            if trans == "passthrough":
                trans = FunctionTransformer(
                    accept_sparse=True,
                    check_inverse=False,
                    feature_names_out="one-to-one",
                ).set_output(transform=output_config["dense"])
            elif trans == "drop":
                continue
            elif _is_empty_column_selection(columns):
                continue

        if column_as_strings:
            # Convert all columns to using their string labels
            columns_is_scalar = np.isscalar(columns)

            indices = self._transformer_to_input_indices[name]
            columns = self.feature_names_in_[indices]

            if columns_is_scalar:
                # selection is done with one dimension
                columns = columns[0]

        yield (name, trans, columns, get_weight(name))

def _validate_transformers(self):
    if not self.transformers:
        return

    names, transformers, _ = zip(*self.transformers)

    # validate names
    self._validate_names(names)

    # validate estimators
    for t in transformers:
        if t in ("drop", "passthrough"):
            continue
        if not (hasattr(t, "fit") or hasattr(t, "fit_transform")) or not hasattr(
            t, "transform"
        ):
            # Used to validate the transformers in the `transformers` list
            raise TypeError(
                "All estimators should implement fit and "
                "transform, or can be 'drop' or 'passthrough' "
                "specifiers. '%s' (type %s) doesn't." % (t, type(t))
            )

def _validate_column_callables(self, X):
    """
    Converts callable column specifications.
    """
    all_columns = []
    transformer_to_input_indices = {}
    for name, _, columns in self.transformers:
        if callable(columns):
            columns = columns(X)
        all_columns.append(columns)
        transformer_to_input_indices[name] = _get_column_indices(X, columns)

    self._columns = all_columns
    self._transformer_to_input_indices = transformer_to_input_indices

def _validate_output(self, result):
    """
    Ensure that the output of each transformer is 2D. Otherwise
    hstack can raise an error or produce incorrect results.
    """
    names = [
        name for name, _, _, _ in self._iter(fitted=True, replace_strings=True)
    ]
    for Xs, name in zip(result, names):
        if not getattr(Xs, "ndim", 0) == 2:
            raise ValueError(
                "The output of the '{0}' transformer should be 2D (scipy "
                "matrix, array, or pandas DataFrame).".format(name)
            )

def _record_output_indices(self, Xs):
    """
    Record which transformer produced which column.
    """
    idx = 0
    self.output_indices_ = {}

    for transformer_idx, (name, _, _, _) in enumerate(
        self._iter(fitted=True, replace_strings=True)
    ):
        n_columns = Xs[transformer_idx].shape[1]
        self.output_indices_[name] = slice(idx, idx + n_columns)
        idx += n_columns

    # `_iter` only generates transformers that have a non empty
    # selection. Here we set empty slices for transformers that
    # generate no output, which are safe for indexing
    all_names = [t[0] for t in self.transformers] + ["remainder"]
    for name in all_names:
        if name not in self.output_indices_:
            self.output_indices_[name] = slice(0, 0)

def prepare_docstring(s: str, ignore: int = None, tabsize: int = 8) -> List[str]:
    """Convert a docstring into lines of parseable reST.  Remove common leading
    indentation, where the indentation of a given number of lines (usually just
    one) is ignored.

    Return the docstring as a list of lines usable for inserting into a docutils
    ViewList (used as argument of nested_parse().)  An empty line is added to
    act as a separator between this docstring and following content.
    """
    if ignore is None:
        ignore = 1
    else:
        warnings.warn("The 'ignore' argument to parepare_docstring() is deprecated.",
                      RemovedInSphinx50Warning, stacklevel=2)

    lines = s.expandtabs(tabsize).splitlines()
    # Find minimum indentation of any non-blank lines after ignored lines.
    margin = sys.maxsize
    for line in lines[ignore:]:
        content = len(line.lstrip())
        if content:
            indent = len(line) - content
            margin = min(margin, indent)
    # Remove indentation from ignored lines.
    for i in range(ignore):
        if i < len(lines):
            lines[i] = lines[i].lstrip()
    if margin < sys.maxsize:
        for i in range(ignore, len(lines)):
            lines[i] = lines[i][margin:]
    # Remove any leading blank lines.
    while lines and not lines[0]:
        lines.pop(0)
    # make sure there is an empty line at the end
    if lines and lines[-1]:
        lines.append('')
    return lines

def _parse_attributes_section(self, section: str) -> List[str]:
    lines = []
    for _name, _type, _desc in self._consume_fields():
        if self._config.napoleon_use_ivar:
            _name = self._qualify_name(_name, self._obj)
            field = ':ivar %s: ' % _name
            lines.extend(self._format_block(field, _desc))
            if _type:
                lines.append(':vartype %s: %s' % (_name, _type))
        else:
            lines.append('.. attribute:: ' + _name)
            if self._opt and 'noindex' in self._opt:
                lines.append('   :noindex:')
            if _type:
                lines.extend(self._indent([':type: %s' % _type], 3))
            lines.append('')

            fields = self._format_field('', '', _desc)
            lines.extend(self._indent(fields, 3))
            lines.append('')
    if self._config.napoleon_use_ivar:
        lines.append('')
    return lines

def _format_block(self, prefix: str, lines: List[str], padding: str = None) -> List[str]:
    if lines:
        if padding is None:
            padding = ' ' * len(prefix)
        result_lines = []
        for i, line in enumerate(lines):
            if i == 0:
                result_lines.append((prefix + line).rstrip())
            elif line:
                result_lines.append(padding + line)
            else:
                result_lines.append('')
        return result_lines
    else:
        return [prefix]

def _consume_fields(self, parse_type: bool = True, prefer_type: bool = False
                    ) -> List[Tuple[str, str, List[str]]]:
    self._consume_empty()
    fields = []
    while not self._is_section_break():
        _name, _type, _desc = self._consume_field(parse_type, prefer_type)
        if _name or _type or _desc:
            fields.append((_name, _type, _desc,))
    return fields

def _escape_args_and_kwargs(self, name: str) -> str:
    if name.endswith('_'):
        name = name[:-1] + r'\_'

    if name[:2] == '**':
        return r'\*\*' + name[2:]
    elif name[:1] == '*':
        return r'\*' + name[1:]
    else:
        return name

def _partition_field_on_colon(self, line: str) -> Tuple[str, str, str]:
    before_colon = []
    after_colon = []
    colon = ''
    found_colon = False
    for i, source in enumerate(_xref_or_code_regex.split(line)):
        if found_colon:
            after_colon.append(source)
        else:
            m = _single_colon_regex.search(source)
            if (i % 2) == 0 and m:
                found_colon = True
                colon = source[m.start(): m.end()]
                before_colon.append(source[:m.start()])
                after_colon.append(source[m.end():])
            else:
                before_colon.append(source)

    return ("".join(before_colon).strip(),
            colon,
            "".join(after_colon).strip())

def _strip_empty(self, lines: List[str]) -> List[str]:
    if lines:
        start = -1
        for i, line in enumerate(lines):
            if line:
                start = i
                break
        if start == -1:
            lines = []
        end = -1
        for i in reversed(range(len(lines))):
            line = lines[i]
            if line:
                end = i
                break
        if start > 0 or end + 1 < len(lines):
            lines = lines[start:end + 1]
    return lines

def a2idx(j, n=None):
    """Return integer after making positive and validating against n."""
    if type(j) is not int:
        try:
            j = j.__index__()
        except AttributeError:
            raise IndexError("Invalid index a[%r]" % (j,))
    if n is not None:
        if j < 0:
            j += n
        if not (j >= 0 and j < n):
            raise IndexError("Index out of range: a[%s]" % (j,))
    return int(j)

def _eval_extract(self, rowsList, colsList):
    urow = list(uniq(rowsList))
    ucol = list(uniq(colsList))
    smat = {}
    if len(urow)*len(ucol) < len(self._smat):
        # there are fewer elements requested than there are elements in the matrix
        for i, r in enumerate(urow):
            for j, c in enumerate(ucol):
                smat[i, j] = self._smat.get((r, c), 0)
    else:
        # most of the request will be zeros so check all of self's entries,
        # keeping only the ones that are desired
        for rk, ck in self._smat:
            if rk in urow and ck in ucol:
                smat[(urow.index(rk), ucol.index(ck))] = self._smat[(rk, ck)]

    rv = self._new(len(urow), len(ucol), smat)
    # rv is nominally correct but there might be rows/cols
    # which require duplication
    if len(rowsList) != len(urow):
        for i, r in enumerate(rowsList):
            i_previous = rowsList.index(r)
            if i_previous != i:
                rv = rv.row_insert(i, rv.row(i_previous))
    if len(colsList) != len(ucol):
        for i, c in enumerate(colsList):
            i_previous = colsList.index(c)
            if i_previous != i:
                rv = rv.col_insert(i, rv.col(i_previous))
    return rv

def __getitem__(self, key):

    if isinstance(key, tuple):
        i, j = key
        try:
            i, j = self.key2ij(key)
            return self._smat.get((i, j), S.Zero)
        except (TypeError, IndexError):
            if isinstance(i, slice):
                # XXX remove list() when PY2 support is dropped
                i = list(range(self.rows))[i]
            elif is_sequence(i):
                pass
            elif isinstance(i, Expr) and not i.is_number:
                from sympy.matrices.expressions.matexpr import MatrixElement
                return MatrixElement(self, i, j)
            else:
                if i >= self.rows:
                    raise IndexError('Row index out of bounds')
                i = [i]
            if isinstance(j, slice):
                # XXX remove list() when PY2 support is dropped
                j = list(range(self.cols))[j]
            elif is_sequence(j):
                pass
            elif isinstance(j, Expr) and not j.is_number:
                from sympy.matrices.expressions.matexpr import MatrixElement
                return MatrixElement(self, i, j)
            else:
                if j >= self.cols:
                    raise IndexError('Col index out of bounds')
                j = [j]
            return self.extract(i, j)

    # check for single arg, like M[:] or M[3]
    if isinstance(key, slice):
        lo, hi = key.indices(len(self))[:2]
        L = []
        for i in range(lo, hi):
            m, n = divmod(i, self.cols)
            L.append(self._smat.get((m, n), S.Zero))
        return L

    i, j = divmod(a2idx(key, len(self)), self.cols)
    return self._smat.get((i, j), S.Zero)

def __init__(self, expr, base_exc=None):
    self.expr = expr
    self.base_exc = base_exc

def _print_MatAdd(self, expr):
    s = None
    for item in expr.args:
        pform = self._print(item)
        if s is None:
            s = pform     # First element
        else:
            if S(item.args[0]).is_negative:
                s = prettyForm(*stringPict.next(s, ' '))
                pform = self._print(item)
            else:
                s = prettyForm(*stringPict.next(s, ' + '))
            s = prettyForm(*stringPict.next(s, pform))

    return s

def _print_Add(self, expr, order=None):
    if self.order == 'none':
        terms = list(expr.args)
    else:
        terms = self._as_ordered_terms(expr, order=order)
    pforms, indices = [], []

    def pretty_negative(pform, index):
        """Prepend a minus sign to a pretty form. """
        #TODO: Move this code to prettyForm
        if index == 0:
            if pform.height() > 1:
                pform_neg = '- '
            else:
                pform_neg = '-'
        else:
            pform_neg = ' - '

        if (pform.binding > prettyForm.NEG
            or pform.binding == prettyForm.ADD):
            p = stringPict(*pform.parens())
        else:
            p = pform
        p = stringPict.next(pform_neg, p)
        # Lower the binding to NEG, even if it was higher. Otherwise, it
        # will print as a + ( - (b)), instead of a - (b).
        return prettyForm(binding=prettyForm.NEG, *p)

    for i, term in enumerate(terms):
        if term.is_Mul and _coeff_isneg(term):
            coeff, other = term.as_coeff_mul(rational=False)
            pform = self._print(Mul(-coeff, *other, evaluate=False))
            pforms.append(pretty_negative(pform, i))
        elif term.is_Rational and term.q > 1:
            pforms.append(None)
            indices.append(i)
        elif term.is_Number and term < 0:
            pform = self._print(-term)
            pforms.append(pretty_negative(pform, i))
        elif term.is_Relational:
            pforms.append(prettyForm(*self._print(term).parens()))
        else:
            pforms.append(self._print(term))

    if indices:
        large = True

        for pform in pforms:
            if pform is not None and pform.height() > 1:
                break
        else:
            large = False

        for i in indices:
            term, negative = terms[i], False

            if term < 0:
                term, negative = -term, True

            if large:
                pform = prettyForm(str(term.p))/prettyForm(str(term.q))
            else:
                pform = self._print(term)

            if negative:
                pform = pretty_negative(pform, i)

            pforms[i] = pform

    return prettyForm.__add__(*pforms)

def _print_Mul(self, product):
    from sympy.physics.units import Quantity
    a = []  # items in the numerator
    b = []  # items that are in the denominator (if any)

    if self.order not in ('old', 'none'):
        args = product.as_ordered_factors()
    else:
        args = list(product.args)

    # If quantities are present append them at the back
    args = sorted(args, key=lambda x: isinstance(x, Quantity) or
                 (isinstance(x, Pow) and isinstance(x.base, Quantity)))

    # Gather terms for numerator/denominator
    for item in args:
        if item.is_commutative and item.is_Pow and item.exp.is_Rational and item.exp.is_negative:
            if item.exp != -1:
                b.append(Pow(item.base, -item.exp, evaluate=False))
            else:
                b.append(Pow(item.base, -item.exp))
        elif item.is_Rational and item is not S.Infinity:
            if item.p != 1:
                a.append( Rational(item.p) )
            if item.q != 1:
                b.append( Rational(item.q) )
        else:
            a.append(item)

    from sympy import Integral, Piecewise, Product, Sum

    # Convert to pretty forms. Add parens to Add instances if there
    # is more than one term in the numer/denom
    for i in range(0, len(a)):
        if (a[i].is_Add and len(a) > 1) or (i != len(a) - 1 and
                isinstance(a[i], (Integral, Piecewise, Product, Sum))):
            a[i] = prettyForm(*self._print(a[i]).parens())
        elif a[i].is_Relational:
            a[i] = prettyForm(*self._print(a[i]).parens())
        else:
            a[i] = self._print(a[i])

    for i in range(0, len(b)):
        if (b[i].is_Add and len(b) > 1) or (i != len(b) - 1 and
                isinstance(b[i], (Integral, Piecewise, Product, Sum))):
            b[i] = prettyForm(*self._print(b[i]).parens())
        else:
            b[i] = self._print(b[i])

    # Construct a pretty form
    if len(b) == 0:
        return prettyForm.__mul__(*a)
    else:
        if len(a) == 0:
            a.append( self._print(S.One) )
        return prettyForm.__mul__(*a)/prettyForm.__mul__(*b)

def _print_Pow(self, power):
    from sympy.simplify.simplify import fraction
    b, e = power.as_base_exp()
    if power.is_commutative:
        if e is S.NegativeOne:
            return prettyForm("1")/self._print(b)
        n, d = fraction(e)
        if n is S.One and d.is_Atom and not e.is_Integer and self._settings['root_notation']:
            return self._print_nth_root(b, e)
        if e.is_Rational and e < 0:
            return prettyForm("1")/self._print(Pow(b, -e, evaluate=False))

    if b.is_Relational:
        return prettyForm(*self._print(b).parens()).__pow__(self._print(e))

    return self._print(b)**self._print(e)

def _print_Symbol(self, e, bold_name=False):
    symb = pretty_symbol(e.name, bold_name)
    return prettyForm(symb)

def merge_solution(var, var_t, solution):
    """
    This is used to construct the full solution from the solutions of sub
    equations.

    For example when solving the equation `(x - y)(x^2 + y^2 - z^2) = 0`,
    solutions for each of the equations `x - y = 0` and `x^2 + y^2 - z^2` are
    found independently. Solutions for `x - y = 0` are `(x, y) = (t, t)`. But
    we should introduce a value for z when we output the solution for the
    original equation. This function converts `(t, t)` into `(t, t, n_{1})`
    where `n_{1}` is an integer parameter.
    """
    sol = []

    if None in solution:
        return ()

    solution = iter(solution)
    params = numbered_symbols("n", integer=True, start=1)
    for v in var:
        if v in var_t:
            sol.append(next(solution))
        else:
            sol.append(next(params))

    for val, symb in zip(sol, var):
        if check_assumptions(val, **symb.assumptions0) is False:
            return tuple()

    return tuple(sol)

def diop_solve(eq, param=symbols("t", integer=True)):
    """
    Solves the diophantine equation ``eq``.

    Unlike ``diophantine()``, factoring of ``eq`` is not attempted. Uses
    ``classify_diop()`` to determine the type of the equation and calls
    the appropriate solver function.

    Use of ``diophantine()`` is recommended over other helper functions.
    ``diop_solve()`` can return either a set or a tuple depending on the
    nature of the equation.

    Usage
    =====

    ``diop_solve(eq, t)``: Solve diophantine equation, ``eq`` using ``t``
    as a parameter if needed.

    Details
    =======

    ``eq`` should be an expression which is assumed to be zero.
    ``t`` is a parameter to be used in the solution.

    Examples
    ========

    >>> from sympy.solvers.diophantine import diop_solve
    >>> from sympy.abc import x, y, z, w
    >>> diop_solve(2*x + 3*y - 5)
    (3*t_0 - 5, 5 - 2*t_0)
    >>> diop_solve(4*x + 3*y - 4*z + 5)
    (t_0, 8*t_0 + 4*t_1 + 5, 7*t_0 + 3*t_1 + 5)
    >>> diop_solve(x + 3*y - 4*z + w - 6)
    (t_0, t_0 + t_1, 6*t_0 + 5*t_1 + 4*t_2 - 6, 5*t_0 + 4*t_1 + 3*t_2 - 6)
    >>> diop_solve(x**2 + y**2 - 5)
    {(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)}


    See Also
    ========

    diophantine()
    """
    var, coeff, eq_type = classify_diop(eq, _dict=False)

    if eq_type == "linear":
        return _diop_linear(var, coeff, param)

    elif eq_type == "binary_quadratic":
        return _diop_quadratic(var, coeff, param)

    elif eq_type == "homogeneous_ternary_quadratic":
        x_0, y_0, z_0 = _diop_ternary_quadratic(var, coeff)
        return _parametrize_ternary_quadratic(
            (x_0, y_0, z_0), var, coeff)

    elif eq_type == "homogeneous_ternary_quadratic_normal":
        x_0, y_0, z_0 = _diop_ternary_quadratic_normal(var, coeff)
        return _parametrize_ternary_quadratic(
            (x_0, y_0, z_0), var, coeff)

    elif eq_type == "general_pythagorean":
        return _diop_general_pythagorean(var, coeff, param)

    elif eq_type == "univariate":
        return set([(int(i),) for i in solveset_real(
            eq, var[0]).intersect(S.Integers)])

    elif eq_type == "general_sum_of_squares":
        return _diop_general_sum_of_squares(var, -int(coeff[1]), limit=S.Infinity)

    elif eq_type == "general_sum_of_even_powers":
        for k in coeff.keys():
            if k.is_Pow and coeff[k]:
                p = k.exp
        return _diop_general_sum_of_even_powers(var, p, -int(coeff[1]), limit=S.Infinity)

    if eq_type is not None and eq_type not in diop_known:
            raise ValueError(filldedent('''
    Alhough this type of equation was identified, it is not yet
    handled. It should, however, be listed in `diop_known` at the
    top of this file. Developers should see comments at the end of
    `classify_diop`.
            '''))  # pragma: no cover
    else:
        raise NotImplementedError(
            'No solver has been written for %s.' % eq_type)

def classify_diop(eq, _dict=True):
    # docstring supplied externally
    try:
        var = list(eq.free_symbols)
        assert var
    except (AttributeError, AssertionError):
        raise ValueError('equation should have 1 or more free symbols')
    var.sort(key=default_sort_key)
    eq = eq.expand(force=True)
    coeff = eq.as_coefficients_dict()
    if not all(_is_int(c) for c in coeff.values()):
        raise TypeError("Coefficients should be Integers")

    diop_type = None
    total_degree = Poly(eq).total_degree()
    homogeneous = 1 not in coeff
    if total_degree == 1:
        diop_type = "linear"

    elif len(var) == 1:
        diop_type = "univariate"

    elif total_degree == 2 and len(var) == 2:
        diop_type = "binary_quadratic"

    elif total_degree == 2 and len(var) == 3 and homogeneous:
        if set(coeff) & set(var):
            diop_type = "inhomogeneous_ternary_quadratic"
        else:
            nonzero = [k for k in coeff if coeff[k]]
            if len(nonzero) == 3 and all(i**2 in nonzero for i in var):
                diop_type = "homogeneous_ternary_quadratic_normal"
            else:
                diop_type = "homogeneous_ternary_quadratic"

    elif total_degree == 2 and len(var) >= 3:
        if set(coeff) & set(var):
            diop_type = "inhomogeneous_general_quadratic"
        else:
            # there may be Pow keys like x**2 or Mul keys like x*y
            if any(k.is_Mul for k in coeff):  # cross terms
                if not homogeneous:
                    diop_type = "inhomogeneous_general_quadratic"
                else:
                    diop_type = "homogeneous_general_quadratic"
            else:  # all squares: x**2 + y**2 + ... + constant
                if all(coeff[k] == 1 for k in coeff if k != 1):
                    diop_type = "general_sum_of_squares"
                elif all(is_square(abs(coeff[k])) for k in coeff):
                    if abs(sum(sign(coeff[k]) for k in coeff)) == \
                            len(var) - 2:
                        # all but one has the same sign
                        # e.g. 4*x**2 + y**2 - 4*z**2
                        diop_type = "general_pythagorean"

    elif total_degree == 3 and len(var) == 2:
        diop_type = "cubic_thue"

    elif (total_degree > 3 and total_degree % 2 == 0 and
            all(k.is_Pow and k.exp == total_degree for k in coeff if k != 1)):
        if all(coeff[k] == 1 for k in coeff if k != 1):
            diop_type = 'general_sum_of_even_powers'

    if diop_type is not None:
        return var, dict(coeff) if _dict else coeff, diop_type

    # new diop type instructions
    # --------------------------
    # if this error raises and the equation *can* be classified,
    #  * it should be identified in the if-block above
    #  * the type should be added to the diop_known
    # if a solver can be written for it,
    #  * a dedicated handler should be written (e.g. diop_linear)
    #  * it should be passed to that handler in diop_solve
    raise NotImplementedError(filldedent('''
        This equation is not yet recognized or else has not been
        simplified sufficiently to put it in a form recognized by
        diop_classify().'''))

def base_solution_linear(c, a, b, t=None):
    """
    Return the base solution for the linear equation, `ax + by = c`.

    Used by ``diop_linear()`` to find the base solution of a linear
    Diophantine equation. If ``t`` is given then the parametrized solution is
    returned.

    Usage
    =====

    ``base_solution_linear(c, a, b, t)``: ``a``, ``b``, ``c`` are coefficients
    in `ax + by = c` and ``t`` is the parameter to be used in the solution.

    Examples
    ========

    >>> from sympy.solvers.diophantine import base_solution_linear
    >>> from sympy.abc import t
    >>> base_solution_linear(5, 2, 3) # equation 2*x + 3*y = 5
    (-5, 5)
    >>> base_solution_linear(0, 5, 7) # equation 5*x + 7*y = 0
    (0, 0)
    >>> base_solution_linear(5, 2, 3, t) # equation 2*x + 3*y = 5
    (3*t - 5, 5 - 2*t)
    >>> base_solution_linear(0, 5, 7, t) # equation 5*x + 7*y = 0
    (7*t, -5*t)
    """
    a, b, c = _remove_gcd(a, b, c)

    if c == 0:
        if t is not None:
            if b < 0:
                t = -t
            return (b*t , -a*t)
        else:
            return (0, 0)
    else:
        x0, y0, d = igcdex(abs(a), abs(b))

        x0 *= sign(a)
        y0 *= sign(b)

        if divisible(c, d):
            if t is not None:
                if b < 0:
                    t = -t
                return (c*x0 + b*t, c*y0 - a*t)
            else:
                return (c*x0, c*y0)
        else:
            return (None, None)

def _remove_gcd(*x):
    try:
        g = igcd(*x)
    except ValueError:
        fx = list(filter(None, x))
        if len(fx) < 2:
            return x
        g = igcd(*[i.as_content_primitive()[0] for i in fx])
    except TypeError:
        raise TypeError('_remove_gcd(a,b,c) or _remove_gcd(*container)')
    if g == 1:
        return x
    return tuple([i//g for i in x])

def gcd_list(seq, *gens, **args):
    """
    Compute GCD of a list of polynomials.

    Examples
    ========

    >>> from sympy import gcd_list
    >>> from sympy.abc import x

    >>> gcd_list([x**3 - 1, x**2 - 1, x**2 - 3*x + 2])
    x - 1

    """
    seq = sympify(seq)

    def try_non_polynomial_gcd(seq):
        if not gens and not args:
            domain, numbers = construct_domain(seq)

            if not numbers:
                return domain.zero
            elif domain.is_Numerical:
                result, numbers = numbers[0], numbers[1:]

                for number in numbers:
                    result = domain.gcd(result, number)

                    if domain.is_one(result):
                        break

                return domain.to_sympy(result)

        return None

    result = try_non_polynomial_gcd(seq)

    if result is not None:
        return result

    options.allowed_flags(args, ['polys'])

    try:
        polys, opt = parallel_poly_from_expr(seq, *gens, **args)

        # gcd for domain Q[irrational] (purely algebraic irrational)
        if len(seq) > 1 and all(elt.is_algebraic and elt.is_irrational for elt in seq):
            a = seq[-1]
            lst = [ (a/elt).ratsimp() for elt in seq[:-1] ]
            if all(frc.is_rational for frc in lst):
                lc = 1
                for frc in lst:
                    lc = lcm(lc, frc.as_numer_denom()[0])
                return a/lc

    except PolificationFailed as exc:
        result = try_non_polynomial_gcd(exc.exprs)

        if result is not None:
            return result
        else:
            raise ComputationFailed('gcd_list', len(seq), exc)

    if not polys:
        if not opt.polys:
            return S.Zero
        else:
            return Poly(0, opt=opt)

    result, polys = polys[0], polys[1:]

    for poly in polys:
        result = result.gcd(poly)

        if result.is_one:
            break

    if not opt.polys:
        return result.as_expr()
    else:
        return result

