                    else:
                        node.append(arg2)
                elif op_type == self.PREFIX:
                    assert grouping_strat is None
                    if pointer == size - 1 or self._is_op(tokens[pointer + 1]):
                        tokens[pointer] = self._missing_arguments_default[token]()
                    else:
                        node.append(tokens.pop(pointer+1))
                        size -= 1
                elif op_type == self.POSTFIX:
                    assert grouping_strat is None
                    if pointer == 0 or self._is_op(tokens[pointer - 1]):
                        tokens[pointer] = self._missing_arguments_default[token]()
                    else:
                        node.append(tokens.pop(pointer-1))
                        pointer -= 1
                        size -= 1
                if isinstance(op_name, Callable):  # type: ignore
                    op_call: Callable = typing.cast(Callable, op_name)
                    new_node = op_call(*node)
                    node.clear()
                    if isinstance(new_node, list):
                        node.extend(new_node)
                    else:
                        tokens[pointer] = new_node
            pointer += 1
    if len(tokens) > 1 or (len(lines) == 0 and len(tokens) == 0):
        if changed:
            # Trick to deal with cases in which an operator with lower
            # precedence should be transformed before an operator of higher
            # precedence. Such as in the case of `#&[x]` (that is
            # equivalent to `Lambda(d_, d_)(x)` in SymPy). In this case the
            # operator `&` has lower precedence than `[`, but needs to be
            # evaluated first because otherwise `# (&[x])` is not a valid
            # expression:
            return self._parse_after_braces(tokens, inside_enclosure)
        raise SyntaxError("unable to create a single AST for the expression")
    if len(lines) > 0:
        if tokens[0] and tokens[0][0] == "CompoundExpression":
            tokens = tokens[0][1:]
        compound_expression = ["CompoundExpression", *lines, *tokens]
        return compound_expression
    return tokens[0]

def temporary_file_path(self):
    """Return the full path of this file."""
    return self.file.name

def _save(self, name, content):
    full_path = self.path(name)

    # Create any intermediate directories that do not exist.
    directory = os.path.dirname(full_path)
    try:
        if self.directory_permissions_mode is not None:
            # os.makedirs applies the global umask, so we reset it,
            # for consistency with file_permissions_mode behavior.
            old_umask = os.umask(0)
            try:
                os.makedirs(directory, self.directory_permissions_mode, exist_ok=True)
            finally:
                os.umask(old_umask)
        else:
            os.makedirs(directory, exist_ok=True)
    except FileExistsError:
        raise FileExistsError('%s exists and is not a directory.' % directory)

    # There's a potential race condition between get_available_name and
    # saving the file; it's possible that two threads might return the
    # same name, at which point all sorts of fun happens. So we need to
    # try to create the file, but if it already exists we have to go back
    # to get_available_name() and try again.

    while True:
        try:
            # This file has a file path that we can move.
            if hasattr(content, 'temporary_file_path'):
                file_move_safe(content.temporary_file_path(), full_path)

            # This is a normal uploadedfile that we can stream.
            else:
                # The current umask value is masked out by os.open!
                fd = os.open(full_path, self.OS_OPEN_FLAGS, 0o666)
                _file = None
                try:
                    locks.lock(fd, locks.LOCK_EX)
                    for chunk in content.chunks():
                        if _file is None:
                            mode = 'wb' if isinstance(chunk, bytes) else 'wt'
                            _file = os.fdopen(fd, mode)
                        _file.write(chunk)
                finally:
                    locks.unlock(fd)
                    if _file is not None:
                        _file.close()
                    else:
                        os.close(fd)
        except FileExistsError:
            # A new name is needed if the file exists.
            name = self.get_available_name(name)
            full_path = self.path(name)
        else:
            # OK, the file save worked. Break out of the loop.
            break

    if self.file_permissions_mode is not None:
        os.chmod(full_path, self.file_permissions_mode)

    # Store filenames with forward slashes, even on Windows.
    return name.replace('\\', '/')

def chunks(self, chunk_size=None):
    """
    Read the file and yield chunks of ``chunk_size`` bytes (defaults to
    ``File.DEFAULT_CHUNK_SIZE``).
    """
    chunk_size = chunk_size or self.DEFAULT_CHUNK_SIZE
    try:
        self.seek(0)
    except (AttributeError, UnsupportedOperation):
        pass

    while True:
        data = self.read(chunk_size)
        if not data:
            break
        yield data

def deconstruct(self):
    kwargs = {
        'model_name': self.model_name,
        'name': self.name,
        'field': self.field,
    }
    if self.preserve_default is not True:
        kwargs['preserve_default'] = self.preserve_default
    return (
        self.__class__.__name__,
        [],
        kwargs
    )

def from_model(cls, model, exclude_rels=False):
    """Given a model, return a ModelState representing it."""
    # Deconstruct the fields
    fields = []
    for field in model._meta.local_fields:
        if getattr(field, "remote_field", None) and exclude_rels:
            continue
        if isinstance(field, OrderWrt):
            continue
        name = field.name
        try:
            fields.append((name, field.clone()))
        except TypeError as e:
            raise TypeError("Couldn't reconstruct field %s on %s: %s" % (
                name,
                model._meta.label,
                e,
            ))
    if not exclude_rels:
        for field in model._meta.local_many_to_many:
            name = field.name
            try:
                fields.append((name, field.clone()))
            except TypeError as e:
                raise TypeError("Couldn't reconstruct m2m field %s on %s: %s" % (
                    name,
                    model._meta.object_name,
                    e,
                ))
    # Extract the options
    options = {}
    for name in DEFAULT_NAMES:
        # Ignore some special options
        if name in ["apps", "app_label"]:
            continue
        elif name in model._meta.original_attrs:
            if name == "unique_together":
                ut = model._meta.original_attrs["unique_together"]
                options[name] = set(normalize_together(ut))
            elif name == "index_together":
                it = model._meta.original_attrs["index_together"]
                options[name] = set(normalize_together(it))
            elif name == "indexes":
                indexes = [idx.clone() for idx in model._meta.indexes]
                for index in indexes:
                    if not index.name:
                        index.set_name_with_model(model)
                options['indexes'] = indexes
            elif name == 'constraints':
                options['constraints'] = [con.clone() for con in model._meta.constraints]
            else:
                options[name] = model._meta.original_attrs[name]
    # If we're ignoring relationships, remove all field-listing model
    # options (that option basically just means "make a stub model")
    if exclude_rels:
        for key in ["unique_together", "index_together", "order_with_respect_to"]:
            if key in options:
                del options[key]
    # Private fields are ignored, so remove options that refer to them.
    elif options.get('order_with_respect_to') in {field.name for field in model._meta.private_fields}:
        del options['order_with_respect_to']

    def flatten_bases(model):
        bases = []
        for base in model.__bases__:
            if hasattr(base, "_meta") and base._meta.abstract:
                bases.extend(flatten_bases(base))
            else:
                bases.append(base)
        return bases

    # We can't rely on __mro__ directly because we only want to flatten
    # abstract models and not the whole tree. However by recursing on
    # __bases__ we may end up with duplicates and ordering issues, we
    # therefore discard any duplicates and reorder the bases according
    # to their index in the MRO.
    flattened_bases = sorted(set(flatten_bases(model)), key=lambda x: model.__mro__.index(x))

    # Make our record
    bases = tuple(
        (
            base._meta.label_lower
            if hasattr(base, "_meta") else
            base
        )
        for base in flattened_bases
    )
    # Ensure at least one base inherits from models.Model
    if not any((isinstance(base, str) or issubclass(base, models.Model)) for base in bases):
        bases = (models.Model,)

    managers = []
    manager_names = set()
    default_manager_shim = None
    for manager in model._meta.managers:
        if manager.name in manager_names:
            # Skip overridden managers.
            continue
        elif manager.use_in_migrations:
            # Copy managers usable in migrations.
            new_manager = copy.copy(manager)
            new_manager._set_creation_counter()
        elif manager is model._base_manager or manager is model._default_manager:
            # Shim custom managers used as default and base managers.
            new_manager = models.Manager()
            new_manager.model = manager.model
            new_manager.name = manager.name
            if manager is model._default_manager:
                default_manager_shim = new_manager
        else:
            continue
        manager_names.add(manager.name)
        managers.append((manager.name, new_manager))

    # Ignore a shimmed default manager called objects if it's the only one.
    if managers == [('objects', default_manager_shim)]:
        managers = []

    # Construct the new ModelState
    return cls(
        model._meta.app_label,
        model._meta.object_name,
        fields,
        options,
        bases,
        managers,
    )

def deconstruct(self):
    kwargs = {
        'model_name': self.model_name,
        'name': self.name,
        'field': self.field,
    }
    if self.preserve_default is not True:
        kwargs['preserve_default'] = self.preserve_default
    return (
        self.__class__.__name__,
        [],
        kwargs
    )

def __init__(self, sql, params, output_field=None):
    if output_field is None:
        output_field = fields.Field()
    self.sql, self.params = sql, params
    super().__init__(output_field=output_field)

def add_ordering(self, *ordering):
    """
    Add items from the 'ordering' sequence to the query's "order by"
    clause. These items are either field names (not column names) --
    possibly with a direction prefix ('-' or '?') -- or OrderBy
    expressions.

    If 'ordering' is empty, clear all ordering from the query.
    """
    errors = []
    for item in ordering:
        if not hasattr(item, 'resolve_expression') and not ORDER_PATTERN.match(item):
            errors.append(item)
        if getattr(item, 'contains_aggregate', False):
            raise FieldError(
                'Using an aggregate in order_by() without also including '
                'it in annotate() is not allowed: %s' % item
            )
    if errors:
        raise FieldError('Invalid order_by arguments: %s' % errors)
    if ordering:
        self.order_by += ordering
    else:
        self.default_ordering = False

def as_sql(self, compiler, connection):
    sql, params = self.get_compiler(connection=connection).as_sql()
    if self.subquery:
        sql = '(%s)' % sql
    return sql, params

def compile(self, node, select_format=False):
    vendor_impl = getattr(node, 'as_' + self.connection.vendor, None)
    if vendor_impl:
        sql, params = vendor_impl(self, self.connection)
    else:
        sql, params = node.as_sql(self, self.connection)
    if select_format is FORCE or (select_format and not self.query.subquery):
        return node.output_field.select_format(self, sql, params)
    return sql, params

def prepare_value(self, value):
    if isinstance(value, datetime.timedelta):
        return duration_string(value)
    return value

def value_to_string(self, obj):
    val = self.value_from_object(obj)
    return '' if val is None else duration_string(val)

def duration_string(duration):
    """Version of str(timedelta) which is not English specific."""
    days, hours, minutes, seconds, microseconds = _get_duration_components(duration)

    string = '{:02d}:{:02d}:{:02d}'.format(hours, minutes, seconds)
    if days:
        string = '{} '.format(days) + string
    if microseconds:
        string += '.{:06d}'.format(microseconds)

    return string

def formfield(self, **kwargs):
    return super().formfield(**{
        'form_class': forms.DurationField,
        **kwargs,
    })

def duration_iso_string(duration):
    if duration < datetime.timedelta(0):
        sign = '-'
        duration *= -1
    else:
        sign = ''

    days, hours, minutes, seconds, microseconds = _get_duration_components(duration)
    ms = '.{:06d}'.format(microseconds) if microseconds else ""
    return '{}P{}DT{:02d}H{:02d}M{:02d}{}S'.format(sign, days, hours, minutes, seconds, ms)

def _convert_to_charset(self, value, charset, mime_encode=False):
    """
    Convert headers key/value to ascii/latin-1 native strings.

    `charset` must be 'ascii' or 'latin-1'. If `mime_encode` is True and
    `value` can't be represented in the given charset, apply MIME-encoding.
    """
    if not isinstance(value, (bytes, str)):
        value = str(value)
    if ((isinstance(value, bytes) and (b'\n' in value or b'\r' in value)) or
            isinstance(value, str) and ('\n' in value or '\r' in value)):
        raise BadHeaderError("Header values can't contain newlines (got %r)" % value)
    try:
        if isinstance(value, str):
            # Ensure string is valid in given charset
            value.encode(charset)
        else:
            # Convert bytestring using given charset
            value = value.decode(charset)
    except UnicodeError as e:
        if mime_encode:
            value = Header(value, 'utf-8', maxlinelen=sys.maxsize).encode()
        else:
            e.reason += ', HTTP response headers must be in %s format' % charset
            raise
    return value

def clean(self):
    super().clean()
    self.email = self.__class__.objects.normalize_email(self.email)

def snapshot_files(self):
    # watched_files may produce duplicate paths if globs overlap.
    seen_files = set()
    for file in self.watched_files():
        if file in seen_files:
            continue
        try:
            mtime = file.stat().st_mtime
        except OSError:
            # This is thrown when the file does not exist.
            continue
        seen_files.add(file)
        yield file, mtime

def watch_file(self, path):
    path = Path(path)
    if not path.is_absolute():
        raise ValueError('%s must be absolute.' % path)
    logger.debug('Watching file %s.', path)
    self.extra_files.add(path)

def run(self, **options):
    """Run the server, using the autoreloader if needed."""
    use_reloader = options['use_reloader']

    if use_reloader:
        autoreload.run_with_reloader(self.inner_run, **options)
    else:
        self.inner_run(None, **options)

def run_with_reloader(main_func, *args, **kwargs):
    signal.signal(signal.SIGTERM, lambda *args: sys.exit(0))
    try:
        if os.environ.get(DJANGO_AUTORELOAD_ENV) == 'true':
            reloader = get_reloader()
            logger.info('Watching for file changes with %s', reloader.__class__.__name__)
            start_django(reloader, main_func, *args, **kwargs)
        else:
            exit_code = restart_with_reloader()
            sys.exit(exit_code)
    except KeyboardInterrupt:
        pass

def get_reloader():
    """Return the most suitable reloader for this environment."""
    try:
        WatchmanReloader.check_availability()
    except WatchmanUnavailable:
        return StatReloader()
    return WatchmanReloader()

def check_availability(cls):
    if not pywatchman:
        raise WatchmanUnavailable('pywatchman not installed.')
    client = pywatchman.client(timeout=0.1)
    try:
        result = client.capabilityCheck()
    except Exception:
        # The service is down?
        raise WatchmanUnavailable('Cannot connect to the watchman service.')
    version = get_version_tuple(result['version'])
    # Watchman 4.9 includes multiple improvements to watching project
    # directories as well as case insensitive filesystems.
    logger.debug('Watchman version %s', version)
    if version < (4, 9):
        raise WatchmanUnavailable('Watchman 4.9 or later is required.')

def watched_files(self, include_globs=True):
    """
    Yield all files that need to be watched, including module files and
    files within globs.
    """
    yield from iter_all_python_module_files()
    yield from self.extra_files
    if include_globs:
        for directory, patterns in self.directory_globs.items():
            for pattern in patterns:
                yield from directory.glob(pattern)

def handle_token(cls, parser, token, name):
    """
    Class method to parse prefix node and return a Node.
    """
    # token.split_contents() isn't useful here because tags using this method don't accept variable as arguments
    tokens = token.contents.split()
    if len(tokens) > 1 and tokens[1] != 'as':
        raise template.TemplateSyntaxError(
            "First argument in '%s' must be 'as'" % tokens[0])
    if len(tokens) > 1:
        varname = tokens[2]
    else:
        varname = None
    return cls(varname, name)

def handle_simple(cls, name):
    try:
        from django.conf import settings
    except ImportError:
        prefix = ''
    else:
        prefix = iri_to_uri(getattr(settings, name, ''))
    return prefix

def handle_token(cls, parser, token):
    """
    Class method to parse prefix node and return a Node.
    """
    bits = token.split_contents()

    if len(bits) < 2:
        raise template.TemplateSyntaxError(
            "'%s' takes at least one argument (path to file)" % bits[0])

    path = parser.compile_filter(bits[1])

    if len(bits) >= 2 and bits[-2] == 'as':
        varname = bits[3]
    else:
        varname = None

    return cls(varname, path)

def handle_simple(cls, path):
    if apps.is_installed('django.contrib.staticfiles'):
        from django.contrib.staticfiles.storage import staticfiles_storage
        return staticfiles_storage.url(path)
    else:
        return urljoin(PrefixNode.handle_simple("STATIC_URL"), quote(path))

def url(self, name):
    if self.base_url is None:
        raise ValueError("This file is not accessible via a URL.")
    url = filepath_to_uri(name)
    if url is not None:
        url = url.lstrip('/')
    return urljoin(self.base_url, url)

def url(self, name, force=False):
    """
    Return the non-hashed URL in DEBUG mode.
    """
    return self._url(self.stored_name, name, force)

def url(self, context):
    path = self.path.resolve(context)
    return self.handle_simple(path)

def _prepare(self, model):
    if self.order_with_respect_to:
        # The app registry will not be ready at this point, so we cannot
        # use get_field().
        query = self.order_with_respect_to
        try:
            self.order_with_respect_to = next(
                f for f in self._get_fields(reverse=False)
                if f.name == query or f.attname == query
            )
        except StopIteration:
            raise FieldDoesNotExist("%s has no field named '%s'" % (self.object_name, query))

        self.ordering = ('_order',)
        if not any(isinstance(field, OrderWrt) for field in model._meta.local_fields):
            model.add_to_class('_order', OrderWrt())
    else:
        self.order_with_respect_to = None

    if self.pk is None:
        if self.parents:
            # Promote the first parent link in lieu of adding yet another
            # field.
            field = next(iter(self.parents.values()))
            # Look for a local field with the same name as the
            # first parent link. If a local field has already been
            # created, use it instead of promoting the parent
            already_created = [fld for fld in self.local_fields if fld.name == field.name]
            if already_created:
                field = already_created[0]
            field.primary_key = True
            self.setup_pk(field)
            if not field.remote_field.parent_link:
                raise ImproperlyConfigured(
                    'Add parent_link=True to %s.' % field,
                )
        else:
            auto = AutoField(verbose_name='ID', primary_key=True, auto_created=True)
            model.add_to_class('id', auto)

def generate_altered_db_table(self):
    models_to_check = self.kept_model_keys.union(self.kept_proxy_keys, self.kept_unmanaged_keys)
    for app_label, model_name in sorted(models_to_check):
        old_model_name = self.renamed_models.get((app_label, model_name), model_name)
        old_model_state = self.from_state.models[app_label, old_model_name]
        new_model_state = self.to_state.models[app_label, model_name]
        old_db_table_name = old_model_state.options.get('db_table')
        new_db_table_name = new_model_state.options.get('db_table')
        if old_db_table_name != new_db_table_name:
            self.add_operation(
                app_label,
                operations.AlterModelTable(
                    name=model_name,
                    table=new_db_table_name,
                )
            )

